using System.ComponentModel; using TransportERP.Desktop.Controls; using TransportERP.Desktop.CoreUI.Controls; using TransportERP.Desktop.Themes; namespace TransportERP.Desktop; /// <summary> /// شاشة GEN-003 — الدول. /// بُنيت من الصفر بواجهة عربية كاملة واتجاه RTL وأزرار تبدأ من أقصى اليمين. /// </summary> public sealed partial class FrmCountries : Form { private readonly BindingList<CountryRow> _countries = new BindingList<CountryRow>(); private readonly TitlePanel _title = new(); private readonly TransportToolbar _toolbar = new(); private readonly SearchBox _search = new(); private readonly TransportDataGrid _grid = new(); private readonly TransportStatusBar _statusBar = new(); private readonly RequiredTextBox _code = Required("يرجى إدخال كود الدولة."); private readonly RequiredTextBox _nameAr = Required("يرجى إدخال اسم الدولة بالعربية."); private readonly RequiredTextBox _nameEn = Required("يرجى إدخال اسم الدولة بالإنجليزية."); private readonly RequiredTextBox _iso2 = Required("يرجى إدخال رمز ISO2."); private readonly RequiredTextBox _iso3 = Required("يرجى إدخال رمز ISO3."); private readonly RequiredTextBox _callingCode = Required("يرجى إدخال مفتاح الاتصال الدولي."); private readonly RequiredTextBox _currencyCode = Required("يرجى إدخال رمز العملة."); private readonly LookupComboBox _status = new(); private readonly RequiredTextBox _notes = new() { IsRequired = false, Multiline = true, ScrollBars = ScrollBars.Vertical }; private readonly Label _recordCount = InfoLabel("عدد السجلات: 0"); private readonly Label _createdInfo = InfoLabel("بيانات الإنشاء: لم يتم الحفظ بعد"); private readonly Label _modifiedInfo = InfoLabel("بيانات التعديل: لا توجد تعديلات"); private readonly Label _editCount = InfoLabel("عدد مرات التعديل: 0"); private readonly Label _printCount = InfoLabel("عدد مرات الطباعة: 0"); private readonly Label _pageNumber = InfoLabel("0 / 0"); private CountryRow? _selected; private bool _hostedInsideDashboard; /// <summary> /// إنشاء الشاشة وتجهيز التصميم وال