{ Dock = DockStyle.Fill, BackColor = Color.White, Padding = new Padding(14, 8, 14, 8) }; _search.PlaceholderText = "ابحث بالكود أو الاسم أو ISO..."; _search.Dock = DockStyle.Right; _search.Width = 440; _recordCount.Dock = DockStyle.Left; _recordCount.Width = 220; panel.Controls.Add(_recordCount); panel.Controls.Add(_search); return panel; } /// <summary> /// إنشاء بطاقة الحقول الرئيسية في عمودين متساويين. /// </summary> private Control BuildDataCard() { var card = new Panel { Dock = DockStyle.Fill, BackColor = Color.White, Padding = new Padding(22, 14, 22, 12) }; var heading = new Label { Dock = DockStyle.Top, Height = 34, Text = "البيانات الرئيسية", Font = UiTheme.CreateBoldFont(14F), ForeColor = UiTheme.HeadingText, TextAlign = ContentAlignment.MiddleRight }; var fields = new TableLayoutPanel { Dock = DockStyle.Fill, ColumnCount = 4, RowCount = 5, Padding = new Padding(0, 8, 0, 0), RightToLeft = RightToLeft.Yes }; fields.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 145F)); fields.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 50F)); fields.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 145F)); fields.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 50F)); for (var row = 0; row < 5; row++) fields.RowStyles.Add(new RowStyle(SizeType.Percent, 20F)); AddField(fields, 0, 0, "كود الدولة *", _code); AddField(fields, 2, 0, "الاسم العربي *", _nameAr); AddField(fields, 0, 1, "الاسم الإنجليزي *", _nameEn); AddField(fields, 2, 1, "رمز ISO2 *", _iso2); AddField(fields, 0, 2, "رمز ISO3 *", _iso3); AddField(fields, 2, 2, "مفتاح الاتصال *", _callingCode); AddField(fields, 0, 3, "رمز العملة *", _currencyCode); AddField(fields, 2, 3, "الحالة *", _status); AddField(fields, 0, 4, "الملاحظات", _notes); fields.SetColumnSpan(_notes, 3); var audit = new FlowLayoutPanel { Dock = DockStyle.Bottom, Height = 30, FlowDirection = FlowDirection.RightToLeft, WrapContents = false }; audit.Controls.AddRange(new Control[] { _createdInfo, _modifiedInfo, _editCount, _printCount }); card.Controls.Add(fields); card.Controls.Add(audit); card.Controls.Add(heading); return card; } /// <summary> /// إنشاء جدول الدول وأزرار التنقل العربية. /// </summary> private Control BuildGridCard() { var card = new Panel { Dock = DockStyle.Fill, BackColor = Color.White, Padding = new Padding(14) }; ConfigureGridColumns(); _grid.Dock = DockStyle.Fill; var pager = new FlowLayoutPanel { Dock = DockStyle.Bottom, Height = 44, FlowDirection = FlowDirection.RightToLeft, WrapContents = false, Padding = new Padding(0, 5, 0, 0) }; pager.Controls.Add(PagerButton("الأول", () => SelectRow(0))); pager.Controls.Add(PagerButton("السابق", () => SelectRow(Math.Max(0, (_grid.CurrentRow?.Index ?? 0) - 1)))); _pageNumber.Width = 90; _pageNumber.Height = 34; _pageNumber.TextAlign = ContentAlignment.MiddleCenter; pager.Controls.Add(_pageNumber); pager.Controls.Add(PagerButton("التالي", () => SelectRow(Math.Min(_grid.Rows.Count - 1, (_grid.CurrentRow?.Index ?? -1) + 1)))); pager.Controls.Add(PagerButton("الأخير", () => SelectRow(_grid.Rows.Count - 1))); card.Controls.Add(_grid); card.Controls.Add(pager); return card; } /// <summary> /// إنشاء عناوين الجدول باللغة العربية. /// </summary> private void ConfigureGridColumns() { _grid.AutoGenerateColumns = false; _grid.Columns.Clear(); AddColumn(nameof(CountryRow.Code), "كود الدولة", 90); AddColumn(nameof(CountryRow.NameAr), "اسم الدولة بالعربية", 180); AddColumn(nameof(CountryRow.NameEn), "اسم الدولة بالإنجليزية", 180); AddColumn(nameof(CountryRow.Iso2), "ISO2", 70); AddColumn(nameof(CountryRow.Iso3), "ISO3", 70); AddColumn(nameof(CountryRow.CallingCode), "مفتاح الاتصال", 105); AddColumn(nameof(CountryRow.CurrencyCode), "رمز العملة", 95); AddColumn(nameof(CountryRow.Status), "الحالة", 90); } /// <summary> /// تسجيل أحداث الأزرار والبحث والجدول. /// </summary> private void RegisterEvents() { _toolbar.NewRequested += (_, _) => StartNewRecord(); _toolbar.SaveRequested += (_, _) => SaveRecord(); _toolbar.EditRequested += (_, _) => EnableFields(true); _toolbar.DisableRequested += (_, _) => StopRecord(); _toolbar.DeleteRequested += (_, _) => DeleteRecord(); _toolbar.PrintRequested += (_, _) => PrintRecord(); _toolbar.CloseRequested += (_, _) => Close(); _search.SearchTextChanged += (_, e) => Filter(e.SearchText); _grid.SelectionChanged += (_, _) => LoadSelectedRecord(); KeyDown += HandleShortcuts; } /// <summary> /// تحميل حالات السجل وبيانات تجريبية مؤقتة. /// </summary> private void LoadData() { _status.BindItems(new[] { "نشط", "موقوف" }); _countries.Add(new CountryRow("YE", "اليمن", "Yemen", "YE", "YEM", "+967", "YER", "نشط", "")); _countries.Add(new CountryRow("SA", "المملكة العربية السعودية", "Saudi Arabia", "SA", "SAU", "+966", "SAR", "نشط", "")); _countries.Add(new CountryRow("AE", "الإمارات العربية المتحدة", "United Arab Emirates", "AE", "ARE", "+971", "AED", "نشط", "")); Bind(_countries); } /// <summary> /// بدء إدخال سجل جديد. /// </summary> private void StartNewRecord() { _selected = null; foreach (var field in TextFields()) field.ResetField(); _status.SelectedIndex = 0; EnableFields(true); _createdInfo.Text = "بيانات الإنشاء: لم يتم الحفظ بعد"; _modifiedInfo.Text = "بيانات التعديل: لا توجد تعديلات"; _editCount.Text = "عدد مرات التعديل: 0"; _code.Focus(); } /// <summary> /// حفظ سجل جديد أو تعديل السجل المحدد. /// </summary> private void SaveRecord() { if (!ValidateFields()) return; if (_selected is null) { _selected = ReadForm(); _countries.Add(_selected); _createdInfo.Text = $"بيانات الإنشاء: المستخدم الحالي — {DateTime.Now:yyyy/MM/dd HH:mm}"; } else { WriteForm(_selected); _selected.EditCount++; _modifiedInfo.Text = $"بيانات التعديل: المستخدم الحالي — {DateTime.Now:yyyy/MM/dd HH:mm}"; _editCount.Text = $"عدد مرات التعديل: {_selected.EditCount}"; } Bind(_countries); EnableFields(false); MessageBox.Show("تم حفظ بيانات الدولة بنجاح.", "الدول", MessageBoxButtons.OK, MessageBoxIcon.Information); } /// <summary> /// التحقق من الحقول الإلزامية. /// </summary> private bool ValidateFields() => _code.ValidateRequired() && _nameAr.ValidateRequired() && _nameEn.ValidateRequired() && _iso2.ValidateRequired() && _iso3.ValidateRequired() && _callingCode.ValidateRequired() && _currencyCode.ValidateRequired() && _status.ValidateSelection(); /// <summary> /// تحميل الصف المحدد إلى الحقول. /// </summary> private void LoadSelectedRecord() { _selected = _grid.GetSelectedItem<CountryRow>(); if (_selected is null) return; _code.Text = _selected.Code; _nameAr.Text = _selected.NameAr; _nameEn.Text = _selected.NameEn; _iso2.Text = _selected.Iso2; _iso3.Text = _selected.Iso3; _callingCode.Text = _selected.CallingCode; _currencyCode.Text = _selected.CurrencyCode; _status.SelectedItem = _selected.Status; _notes.Text = _selected.Notes; _editCount.Text = $"عدد مرات التعديل: {_selected.EditCount}"; EnableFields(false); UpdatePage(); } /// <summary> /// إيقاف السجل المحدد. /// </summary> private void StopRecord() { if (!EnsureSelection()) return; _selected!.Status = "موقوف"; _status.SelectedItem = "موقوف"; _grid.Refresh(); } /// <summary> /// حذف السجل المحدد بعد التأكيد. /// </summary> private void DeleteRecord() { if (!EnsureSelection()) return; var answer = MessageBox.Show("هل تريد حذف الدولة المحددة؟", "تأكيد الحذف", MessageBoxButtons.YesNo, MessageBoxIcon.Warning, MessageBoxDefaultButton.Button2, MessageBoxOptions.RtlReading | MessageBoxOptions.RightAlign); if (answer != DialogResult.Yes) return; _countries.Remove(_selected!); Bind(_countries); StartNewRecord(); } /// <summary> /// تسجيل عملية طباعة تجريبية. /// </summary> private void PrintRecord() { if (!EnsureSelection()) return; _selected!.PrintCount++; _printCount.Text = $"عدد مرات الطباعة: {_selected.PrintCount}"; MessageBox.Show("تم تجهيز بيانات الدولة للطباعة.", "طباعة", MessageBoxButtons.OK, MessageBoxIcon.Information); } /// <summary> /// البحث الفوري في حقول الدولة الأساسية. /// </summary> private void Filter(string text) { if (string.IsNullOrWhiteSpace(text)) { Bind(_countries); return; } var value = text.Trim(); Bind(_countries.Where(x => x.Code.Contains(value, StringComparison.OrdinalIgnoreCase) || x.NameAr.Contains(value, StringComparison.OrdinalIgnoreCase) || x.NameEn.Contains(value, StringComparison.OrdinalIgnoreCase) || x.Iso2.Contains(value, StringComparison.OrdinalIgnoreCase) || x.Iso3.Contains(value, StringComparison.OrdinalIgnoreCase)).ToList()); } /// <summary> /// ربط البيانات بالجدول وتحديث العدد. /// </summary> private void Bind(object source) { _grid.BindData(source); _recordCount.Text = $"عدد السجلات: {_grid.Rows.Count}"; UpdatePage(); } /// <summary> /// تحديد صف حسب رقمه. /// </summary> private void SelectRow(int index) { if (index < 0 || index >= _grid.Rows.Count) return; _grid.ClearSelection(); _grid.Rows[index].Selected = true; _grid.CurrentCell = _grid.Rows[index].Cells[0]; UpdatePage(); } /// <summary> /// تحديث مؤشر السجل الحالي. /// </summary> private void UpdatePage() { var current = _grid.CurrentRow is null ? 0 : _grid.CurrentRow.Index + 1; _pageNumber.Text = $"{current} / {_grid.Rows.Count}"; } /// <summary> /// تهيئة الشاشة للعرض داخل تبويب Dashboard. /// </summary> public void ConfigureForTabHosting() { if (_hostedInsideDashboard) return; _hostedInsideDashboard = true; TopLevel = false; FormBorderStyle = FormBorderStyle.None; Dock = DockStyle.Fill; WindowState = FormWindowState.Normal; ShowInTaskbar = false; _statusBar.Visible = false; } private CountryRow ReadForm() => new(_code.Text.Trim(), _nameAr.Text.Trim(), _nameEn.Text.Trim(), _iso2.Text.Trim().ToUpperInvariant(), _iso3.Text.Trim().ToUpperInvariant(), _callingCode.Text.Trim(), _currencyCode.Text.Trim().ToUpperInvariant(), _status.SelectedItem?.ToString() ?? "نشط", _notes.Text.Trim()); private void WriteForm(CountryRow row) { row.Code = _code.Text.Trim(); row.NameAr = _nameAr.Text.Trim(); row.NameEn = _nameEn.Text.Trim(); row.Iso2 = _iso2.Text.Trim().ToUpperInvariant(); row.Iso3 = _iso3.Text.Trim().ToUpperInvariant(); row.CallingCode = _callingCode.Text.Trim(); row.CurrencyCode = _currencyCode.Text.Trim().ToUpperInvariant(); row.Status = _status.SelectedItem?.ToString() ?? "نشط"; row.Notes = _notes.Text.Trim(); } private bool EnsureSelection() { if (_selected is not null) return true; MessageBox.Show("يرجى تحديد دولة من الجدول أولًا.", "الدول", MessageBoxButtons.OK, MessageBoxIcon.Warning, MessageBoxDefaultButton.Button1, MessageBoxOptions.RtlReading | MessageBoxOptions.RightAlign); return false; } private void EnableFields(bool enabled) { foreach (var control in new Control[] { _code, _nameAr, _nameEn, _iso2, _iso3, _callingCode, _currencyCode, _status, _notes }) control.Enabled = enabled; } private IEnumerable<RequiredTextBox> TextFields() => new RequiredTextBox[] { _code, _nameAr, _nameEn, _iso2, _iso3, _callingCode, _currencyCode, _notes }; private void HandleShortcuts(object? sender, KeyEventArgs e) { if (e.Control && e.KeyCode == Keys.N) { StartNewRecord(); e.SuppressKeyPress = true; } else if (e.Control && e.KeyCode == Keys.S) { SaveRecord(); e.SuppressKeyPress = true; } else if (e.KeyCode == Keys.Escape) Close(); } private static RequiredTextBox Required(string message) => new() { IsRequired = true, RequiredMessage = message, Font = UiTheme.CreateRegularFont(10.5F) }; private static Label InfoLabel(string text) => new() { AutoSize = true, Text = text, Font = UiTheme.CreateRegularFont(8.5F), ForeColor = UiTheme.SecondaryText, Margin = new Padding(18, 0, 0, 0), TextAlign = ContentAlignment.MiddleCenter }; private static void AddField(TableLayoutPanel layout, int labelColumn, int row, string title, Control field) { layout.Controls.Add(new Label { Dock = DockStyle.Fill, Text = title, Font = UiTheme.CreateBoldFont(10F), ForeColor = UiTheme.HeadingText, TextAlign = ContentAlignment.MiddleRight, Margin = new Padding(8, 4, 8, 4) }, labelColumn, row); field.Dock = DockStyle.Fill; field.Margin = new Padding(8, 5, 14, 5); layout.Controls.Add(field, labelColumn + 1, row); } private static PrimaryButton PagerButton(string text, Action action) { var button = new PrimaryButton { Text = text, Width = 84, Height = 34, CornerRadius = 8, Margin = new Padding(4, 0, 4, 0), Font = UiTheme.CreateBoldFont(9F) }; button.Click += (_, _) => action(); return button; } private void AddColumn(string propertyName, string arabicHeader, int width) { _grid.Columns.Add(new DataGridViewTextBoxColumn { DataPropertyName = propertyName, Name = propertyName, HeaderText = arabicHeader, MinimumWidth = width, FillWeight = width, ReadOnly = true, SortMode = DataGridViewColumnSortMode.Automatic }); } /// <summary> /// نموذج العرض المحلي إلى حين إنشاء DTO وربط API. /// </summary> private sealed class CountryRow { public CountryRow(string code, string nameAr, string nameEn, string iso2, string iso3, string callingCode, string currencyCode, string status, string notes) { Code = code; NameAr = nameAr; NameEn = nameEn; Iso2 = iso2; Iso3 = iso3; CallingCode = callingCode; CurrencyCode = currencyCode; Status = status; Notes = notes; } [DisplayName("كود الدولة")] public string Code { get; set; } [DisplayName("الاسم العربي")] public string NameAr { get; set; } [DisplayName("الاسم الإنجليزي")] public string NameEn { get; set; } [DisplayName("رمز ISO2")] public string Iso2 { get; set; } [DisplayName("رمز ISO3")] public string Iso3 { get; set; } [DisplayName("مفتاح الاتصال")] public string CallingCode { get; set; } [DisplayName("رمز العملة")] public string CurrencyCode { get; set; } [DisplayName("الحالة")] public string Status { get; set; } [DisplayName("الملاحظات")] public string Notes { get; set; } [Browsable(false)] public int EditCount { get; set; } [Browsable(false)] public int PrintCount { get; set; } } }